const items = $input.all();
const seen = new Set();
const unique = [];

for (const item of items) {
  const data = Array.isArray(item.json) ? item.json : [item.json];
  for (const post of data) {
    if (!post) continue;
    const textKey = (post.text || post.content?.text || '').substring(0, 120).trim().toLowerCase();
    const id = textKey || post.activity_id || post.full_urn || JSON.stringify(post).substring(0, 80);
    if (!seen.has(id)) {
      seen.add(id);
      unique.push({ json: post });
    }
  }
}

return unique.length > 0 ? unique : [{ json: { error: 'no posts after dedup' } }];

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  if (!d || d.error) continue;

  const postText = d.text || d.content?.text || d.commentary || '';
  const url = d.post_url || d.postUrl || d.url || '';
  const author = d.author?.name || d.authorName || 'Unknown';
  const postedAt = d.posted_at?.date || d.postedAt || 'Unknown';
  const activityId = d.activity_id || d.full_urn || url || postText.substring(0, 60);

  if (postText.length < 30) continue;

  results.push({ json: { postText, url, author, postedAt, activityId } });
}

return results.length > 0 ? results : [{ json: { error: 'no valid posts' } }];

const item = $input.first().json;
const originalPost = $('Loop Over Posts2').item.json;

const raw =
  item?.choices?.[0]?.message?.content ||
  item?.content ||
  '';

try {
  const clean = String(raw)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const parsed = JSON.parse(clean);

  return [{
    json: {
      ...originalPost,
      ...parsed,
      parse_ok: true
    }
  }];
} catch (error) {
  return [{
    json: {
      ...originalPost,
      is_relevant: false,
      parse_ok: false,
      raw_groq_response: raw,
      error: `Groq parse error: ${error.message}`
    }
  }];
}

const current = $('Parse Filter Response1').item.json;
const rows = $('Read Existing Sheet1').all();

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '');
}

const currentCompany = normalize(current.company);

const alreadyProcessed = rows.some((row) => {
  const data = row.json || {};
  const sheetCompany = normalize(data.Company);

  const emailStatus = String(data['Email Status'] ?? '')
    .trim()
    .toLowerCase();

  const dmStatus = String(data['DM Status'] ?? '')
    .trim()
    .toLowerCase();

  return (
    currentCompany &&
    sheetCompany === currentCompany &&
    (
      emailStatus === 'email draft ready' ||
      dmStatus === 'dm draft ready'
    )
  );
});

return [{
  json: {
    ...current,
    skip: alreadyProcessed
  }
}];

const item = $input.first().json;
const filtered = $('Parse Filter Response1').item.json;

const raw =
  item?.candidates?.[0]?.content?.parts?.[0]?.text ||
  item?.choices?.[0]?.message?.content ||
  '';

function valid(value) {
  if (value === null || value === undefined) return false;

  const text = String(value).trim().toLowerCase();

  return (
    text !== '' &&
    text !== 'unknown' &&
    text !== 'not specified' &&
    text !== 'undefined' &&
    text !== 'null'
  );
}

function firstValid(...values) {
  return values.find(valid) ?? 'Unknown';
}

function repairJson(value) {
  let result = '';
  let insideString = false;
  let escaped = false;

  for (const character of String(value)) {
    if (escaped) {
      result += character;
      escaped = false;
      continue;
    }

    if (character === '\\' && insideString) {
      result += character;
      escaped = true;
      continue;
    }

    if (character === '"') {
      insideString = !insideString;
      result += character;
      continue;
    }

    if (insideString && character === '\n') {
      result += '\\n';
    } else if (insideString && character === '\r') {
      result += '\\r';
    } else if (insideString && character === '\t') {
      result += '\\t';
    } else {
      result += character;
    }
  }

  return result;
}

const baseData = {
  postText: filtered.postText,
  url: filtered.url || filtered.post_url || null,
  postedAt: filtered.postedAt || filtered.posted_date || null,
  activityId: filtered.activityId || filtered.activity_id || null,
  author: filtered.author || null
};

if (!raw) {
  return [{
    json: {
      ...baseData,
      ...filtered,
      company: firstValid(filtered.company),
      role: firstValid(filtered.role),
      location: firstValid(filtered.location),
      experience_required: firstValid(filtered.experience_required),
      author_name: firstValid(filtered.author_name, filtered.author),
      email_draft: null,
      dm_draft: null,
      parse_ok: false,
      error: 'Gemini returned empty response'
    }
  }];
}

try {
  const clean = String(raw)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const parsed = JSON.parse(repairJson(clean));

  const contactEmail = valid(filtered.contact_email)
    ? filtered.contact_email
    : valid(parsed.contact_email)
      ? parsed.contact_email
      : null;

  return [{
    json: {
      ...baseData,

      // Trusted job fields: never allow Gemini placeholders to overwrite them
      company: firstValid(filtered.company, parsed.company),
      role: firstValid(filtered.role, parsed.role),
      location: firstValid(filtered.location, parsed.location),
      experience_required: firstValid(
        filtered.experience_required,
        parsed.experience_required
      ),
      match_score: filtered.match_score ?? parsed.match_score ?? 0,

      // Trusted contact and author fields
      has_email: Boolean(contactEmail),
      contact_email: contactEmail,
      has_apply_link: Boolean(
        valid(filtered.apply_link) || valid(parsed.apply_link)
      ),
      apply_link: valid(filtered.apply_link)
        ? filtered.apply_link
        : valid(parsed.apply_link)
          ? parsed.apply_link
          : null,
      author_name: firstValid(
        filtered.author_name,
        filtered.author,
        parsed.author_name
      ),

      post_url: baseData.url,
      posted_date: baseData.postedAt,

      // Only drafts come from Gemini
      email_draft: valid(parsed.email_draft)
        ? parsed.email_draft
        : null,
      dm_draft: valid(parsed.dm_draft)
        ? parsed.dm_draft
        : null,

      parse_ok: true
    }
  }];
} catch (error) {
  return [{
    json: {
      ...baseData,
      ...filtered,
      company: firstValid(filtered.company),
      role: firstValid(filtered.role),
      location: firstValid(filtered.location),
      experience_required: firstValid(filtered.experience_required),
      author_name: firstValid(filtered.author_name, filtered.author),
      email_draft: null,
      dm_draft: null,
      parse_ok: false,
      error: `Gemini parse error: ${error.message}`,
      raw_gemini_response: raw
    }
  }];
}
